import json
import os

# Check ALL channels in CoachForce for market research mentions
d = json.load(open('DATA/products/CoachForce.json'))
channels = set()
for msg in d['slack']:
    channels.add(msg['Channel'].get('name'))
print('Channels:', sorted(channels))
print()
# Check develop channels for market research mentions
for channel in channels:
    if 'develop' in channel or 'bug' in channel:
        for msg in d['slack']:
            if msg['Channel'].get('name') == channel:
                text = msg.get('Message', {}).get('User', {}).get('text', '').lower()
                if 'market_research' in text or 'cofoaix_market' in text:
                    print(f'{channel}: {msg[\"id\"]} | {text[:200]}')
"

